import React, { useState, useEffect } from 'react';

const Hero = () => {
  const [displayText, setDisplayText] = useState('');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [showContent, setShowContent] = useState(false);
  const [showButton, setShowButton] = useState(false);

  const fullText = "Hi, I'm An.";
  const introText = "With a background in audit and software, I enjoy trying new things and exploring different perspectives. I aim to use my skills to make a positive impact in the world";

  useEffect(() => {
    const timer = setTimeout(() => {
      if (currentIndex < fullText.length) {
        setDisplayText(prev => prev + fullText[currentIndex]);
        setCurrentIndex(prev => prev + 1);
      } else {
        setTimeout(() => {
          setShowContent(true);
        }, 1000);
      }
    }, 150);

    return () => clearTimeout(timer);
  }, [currentIndex, fullText.length]);

  useEffect(() => {
    if (showContent) {
      setTimeout(() => {
        setShowButton(true);
      }, 2000);
    }
  }, [showContent]);

  const scrollToSection = (sectionId) => {
    const element = document.getElementById(sectionId);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <section id="hero" className="min-h-screen flex items-center justify-center bg-gray-900 relative overflow-hidden">
      {/* 背景動畫效果 */}
      <div className="absolute inset-0">
        <div className="absolute top-1/4 left-1/4 w-72 h-72 bg-green-500 rounded-full mix-blend-multiply filter blur-xl opacity-10 animate-pulse"></div>
        <div className="absolute top-3/4 right-1/4 w-72 h-72 bg-green-400 rounded-full mix-blend-multiply filter blur-xl opacity-10 animate-pulse animation-delay-2000"></div>
        <div className="absolute bottom-1/4 left-1/3 w-72 h-72 bg-green-600 rounded-full mix-blend-multiply filter blur-xl opacity-10 animate-pulse animation-delay-4000"></div>
      </div>

      <div className="relative z-10 text-center text-white px-6 max-w-4xl mx-auto">
        {/* 打字效果文字 */}
        <div className="mb-8">
          <h1 className="text-5xl md:text-7xl font-bold mb-4">
            <span className="inline-block">
              {displayText}
              <span className="animate-pulse text-blue-400">|</span>
            </span>
          </h1>
        </div>

        {/* 介紹文字 - 淡入效果 */}
        {showContent && (
          <div className="animate-fade-in-up">
            <p className="text-xl md:text-2xl mb-8 text-gray-200 leading-relaxed">
              {introText}
            </p>
            <div className="flex flex-wrap justify-center gap-4 text-lg text-gray-300">
              <span className="px-4 py-2 bg-blue-500/20 rounded-full">React Developer</span>
              <span className="px-4 py-2 bg-purple-500/20 rounded-full">Agile Practitioner</span>
              <span className="px-4 py-2 bg-green-500/20 rounded-full">Problem Solver</span>
            </div>
          </div>
        )}

        {/* 開始按鈕 - 滑入效果 */}
        {showButton && (
          <div className="animate-fade-in-up animation-delay-1000">
            <button 
              className="group relative inline-flex items-center justify-center px-8 py-4 text-lg font-semibold text-white bg-gradient-to-r from-blue-500 to-purple-600 rounded-full hover:from-blue-600 hover:to-purple-700 transform hover:scale-105 transition-all duration-300 shadow-lg hover:shadow-xl"
              onClick={() => scrollToSection('user-stories')}
            >
              <span className="relative z-10 flex items-center">
                開始了解我
                <svg className="ml-2 w-5 h-5 group-hover:translate-x-1 transition-transform duration-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7l5 5m0 0l-5 5m5-5H6" />
                </svg>
              </span>
              <div className="absolute inset-0 bg-gradient-to-r from-blue-600 to-purple-700 rounded-full opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
            </button>
          </div>
        )}
      </div>

      {/* 滾動指示器 */}
      <div className="absolute bottom-8 left-1/2 transform -translate-x-1/2 animate-bounce">
        <div className="w-6 h-10 border-2 border-white/30 rounded-full flex justify-center">
          <div className="w-1 h-3 bg-white/50 rounded-full mt-2 animate-pulse"></div>
        </div>
      </div>
    </section>
  );
};

export default Hero;
